import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"宿主机侧单元测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/host-tests.md","filePath":"zh/dev/host-tests.md"}'),s={name:"zh/dev/host-tests.md"};function r(i,e,c,d,h,n){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="宿主机侧单元测试" tabindex="-1">宿主机侧单元测试 <a class="header-anchor" href="#宿主机侧单元测试" aria-label="Permalink to &quot;宿主机侧单元测试&quot;">​</a></h1><p><code>make test</code> 运行 <code>tools/run_host_tests.py</code>：它在<em>宿主机上</em>编译 并执行 <code>tests/host_*.c</code> 中的测试桩，针对它们所包含的真实内核 源文件。</p><h2 id="运行什么" tabindex="-1">运行什么 <a class="header-anchor" href="#运行什么" aria-label="Permalink to &quot;运行什么&quot;">​</a></h2><p>运行器从每个测试桩的头部注释提取文档化的 gcc 命令行，重映射 重构前的路径（<code>kernel/aead.c</code> -&gt; <code>kernel/crypto/crypto_aead.c</code>， ...），用宿主机工具链编译（在测试桩要求时开 ASAN）并执行。 需要外部夹具（openssl 生成的密钥文件）的测试桩会编译通过但 报告 SKIP-FIXTURE 而不是失败。</p><p>覆盖亮点（每个家族一个测试桩）：</p><ul><li>crypto：NIST AES/SHA/HMAC 向量、RSA、X.509 解析、AEAD</li><li>tar / gzip / string：lib_* 原语</li><li>FAT 结构与 LFN 编码</li><li>multiboot2 解析（含畸形 mbi 场景，ASAN）</li><li>堆与 VMM 不变量</li></ul><h2 id="什么时候运行" tabindex="-1">什么时候运行 <a class="header-anchor" href="#什么时候运行" aria-label="Permalink to &quot;什么时候运行&quot;">​</a></h2><p>始终运行。它是整个循环里最快的信号 - 不需要启动，几秒钟内就 能抓住纯逻辑回归（校验和链、头对齐、边界）。</p><h2 id="新增一个测试桩" tabindex="-1">新增一个测试桩 <a class="header-anchor" href="#新增一个测试桩" aria-label="Permalink to &quot;新增一个测试桩&quot;">​</a></h2><ol><li>创建 <code>tests/host_&lt;name&gt;.c</code>，带标准头部注释，其中包含确切的 编译命令行（标志 + 包含路径）。</li><li>数清你的检查数，并以失败数作为退出码。</li><li><code>make test</code> 会自动发现它。</li></ol><p><a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a> 的规则：绝不为通过 而削弱测试。如果测试本身错了，修测试，<em>并在提交里说明</em>。</p>',11)])])}const m=t(s,[["render",r]]);export{_ as __pageData,m as default};
